CREATE TABLE admins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL DEFAULT 'admin' CHECK(role='admin'), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE session (sid varchar PRIMARY KEY, sess json NOT NULL, expire timestamp NOT NULL);
CREATE INDEX session_expire_idx ON session(expire);
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, slug text NOT NULL UNIQUE, description text NOT NULL DEFAULT '', image text NOT NULL DEFAULT '', position integer NOT NULL DEFAULT 0, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_id uuid REFERENCES categories(id) ON DELETE SET NULL, name text NOT NULL, slug text NOT NULL UNIQUE, sku text NOT NULL UNIQUE, description text NOT NULL DEFAULT '', sizes text NOT NULL DEFAULT '', colours text NOT NULL DEFAULT '', fabric text NOT NULL DEFAULT '', customization text NOT NULL DEFAULT '', moq text NOT NULL DEFAULT '', published boolean NOT NULL DEFAULT false, featured boolean NOT NULL DEFAULT false, demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_category_idx ON products(category_id);
CREATE INDEX products_published_idx ON products(published,featured);
CREATE TABLE product_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, url text NOT NULL, alt text NOT NULL, position integer NOT NULL DEFAULT 0);
CREATE TABLE capabilities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text NOT NULL DEFAULT '', image text NOT NULL DEFAULT '', position integer NOT NULL DEFAULT 0, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE gallery (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text NOT NULL DEFAULT '', image text NOT NULL, category text NOT NULL DEFAULT 'Products', position integer NOT NULL DEFAULT 0, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE content (key text PRIMARY KEY, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE enquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference bigint GENERATED ALWAYS AS IDENTITY UNIQUE, name text NOT NULL, company text NOT NULL, email text NOT NULL, phone text NOT NULL, buyer_type text NOT NULL, category text NOT NULL DEFAULT '', product_id uuid REFERENCES products(id) ON DELETE SET NULL, product_name text NOT NULL DEFAULT '', quantity integer NOT NULL CHECK(quantity>0), customization text NOT NULL DEFAULT '', message text NOT NULL, status text NOT NULL DEFAULT 'New' CHECK(status IN ('New','Contacted','Quotation in Progress','Quotation Sent','Converted','Closed')), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX enquiries_status_created_idx ON enquiries(status,created_at DESC);
CREATE INDEX enquiries_email_idx ON enquiries(email);
CREATE TABLE enquiry_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enquiry_id uuid NOT NULL REFERENCES enquiries(id) ON DELETE CASCADE, admin_id uuid REFERENCES admins(id) ON DELETE SET NULL, status text NOT NULL, note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO content(key,value) VALUES ('site', '{"company":"OSLC","tagline":"Manufacturing Quality. Building Fashion.","heroTitle":"Your Trusted Partner in Men’s Apparel Manufacturing.","heroDescription":"Thoughtful apparel. Professional partnerships. Discuss your next collection with OSLC, based in the textile city of Surat.","about":"OSLC is a textile and men’s apparel manufacturing business based in Kosad, Surat, Gujarat. We welcome conversations with wholesalers, retailers, fashion brands and bulk buyers about their apparel requirements.","mission":"To build lasting business partnerships through a focus on quality, clear communication and agreed product requirements.","vision":"To be a dependable partner for businesses developing their men’s apparel collections.","quality":"Quality starts with a clear brief. Discuss your measurements, fabric preferences, finish and inspection requirements with our team before placing an order.","address":"Sai Chock, Ring Road, Kosad, Surat, Gujarat 394107, India","phone":"","whatsapp":"","email":"","hours":"","heroImage":"","socialLinks":"","seoTitle":"OSLC | Men’s Apparel Manufacturing in Surat","seoDescription":"OSLC House, Kosad, Surat. Discuss textile and men’s apparel manufacturing requirements and bulk business enquiries.","aboutImage":"","process":"","privacy":"We collect the details you submit to respond to your business enquiry and manage our business relationship. Access is restricted to authorized administrators. We do not sell enquiry data. Contact OSLC through the enquiry form for access, correction or deletion requests. Essential session cookies are used for administrator access. Retention periods and the privacy contact must be confirmed by OSLC before public launch.","terms":"This website provides business information and a product enquiry catalogue. Submitting an enquiry does not place an order or establish a supply contract. Specifications, minimum quantities, customization, pricing and delivery terms require written agreement with OSLC. OSLC must review these terms before public launch."}');
